package com.salespunch360.mobile
import android.app.Application;import androidx.lifecycle.AndroidViewModel;import androidx.lifecycle.viewModelScope;import com.salespunch360.mobile.data.*;import java.io.IOException;import kotlinx.coroutines.flow.*;import kotlinx.coroutines.launch;import kotlinx.serialization.json.*
data class MoneyState(val loanOverview:JsonObject?=null,val loanSearch:String="",val loanOffset:Int=0,val historyIsLoan:Boolean=false,val historyIsAccount:Boolean=false,val historyOwnerId:String?=null,val history:JsonObject?=null,val historyLoading:Boolean=false,val historyError:String?=null,val historyFrom:String="",val historyTo:String="",val historyOffset:Int=0,val loading:Boolean=false,val saving:Boolean=false,val mode:String="accounts",val data:JsonObject=buildJsonObject{},val editing:String?=null,val selected:JsonObject?=null,val error:String?=null)
class AccountMoneyViewModel(app:Application):AndroidViewModel(app){private var contextQuery="";private var contextGeneration=0L;private var contextJob:kotlinx.coroutines.Job?=null;private var accountCreationKey=java.util.UUID.randomUUID().toString();private var historyJob:kotlinx.coroutines.Job?=null;private var historyGeneration=0L;private val api=ApiClient(SecureSession(app));private val _state=MutableStateFlow(MoneyState());val state:StateFlow<MoneyState> = _state;init{load()};fun show(m:String,query:String?=null){closeOwnerHistory();if(query!=null&&query!=contextQuery){contextQuery=query;_state.value=_state.value.copy(data=buildJsonObject{},loanOverview=null,loanSearch="",loanOffset=0)};_state.value=_state.value.copy(mode=m,editing=null);load()};fun load(){contextJob?.cancel();val generation=++contextGeneration;val query=contextQuery;_state.value=_state.value.copy(loading=true,error=null);contextJob=viewModelScope.launch{try{val loaded=api.moneyContext(query);val loans=if(_state.value.mode=="loans")api.loanOverview(query,_state.value.loanSearch,_state.value.loanOffset)else null;if(generation==contextGeneration)_state.value=_state.value.copy(loading=false,data=loaded,loanOverview=loans)}catch(e:kotlinx.coroutines.CancellationException){throw e}catch(e:Exception){if(generation==contextGeneration)fail(e)}}};fun searchLoans(value:String){_state.value=_state.value.copy(loanSearch=value)};fun loanPage(offset:Int=0){_state.value=_state.value.copy(loanOffset=offset,loanOverview=null);load()};fun openLoanHistory(id:String){_state.value=_state.value.copy(historyIsLoan=true,historyIsAccount=false,historyOwnerId=id,history=null,historyOffset=0);loadOwnerHistory(0)};fun openMoneyHistory(id:String){_state.value=_state.value.copy(historyIsLoan=false,historyIsAccount=true,historyOwnerId=id,history=null,historyFrom="",historyTo="",historyOffset=0);loadOwnerHistory(0)};fun openOwnerHistory(id:String){_state.value=_state.value.copy(historyIsLoan=false,historyIsAccount=false,historyOwnerId=id,history=null,historyFrom="",historyTo="",historyOffset=0);loadOwnerHistory(0)};fun closeOwnerHistory(){historyGeneration++;historyJob?.cancel();_state.value=_state.value.copy(historyOwnerId=null,history=null,historyLoading=false,historyError=null)};fun historyDates(from:String,to:String){_state.value=_state.value.copy(historyFrom=from,historyTo=to)};fun loadOwnerHistory(offset:Int=0){val id=_state.value.historyOwnerId?:return;val accountHistory=_state.value.historyIsAccount;val loanHistory=_state.value.historyIsLoan;val scopeQuery=contextQuery;val from=_state.value.historyFrom;val to=_state.value.historyTo;historyJob?.cancel();val generation=++historyGeneration;historyJob=viewModelScope.launch{_state.value=_state.value.copy(historyLoading=true,historyError=null);try{val rows=if(loanHistory)api.loanHistory(id,scopeQuery,offset)else if(accountHistory)api.moneyAccountHistory(id,scopeQuery,from,to,offset)else api.ownerHistory(id,from,to,offset);if(generation==historyGeneration)_state.value=_state.value.copy(historyLoading=false,history=rows,historyOffset=offset)}catch(e:kotlinx.coroutines.CancellationException){throw e}catch(e:Exception){if(generation==historyGeneration)_state.value=_state.value.copy(historyLoading=false,historyError=if(e is IOException)"Offline. Reconnect and retry history." else "History could not be loaded. Check the dates and retry.")}}};fun create(kind:String){if(_state.value.saving)return;if(kind=="accounts")accountCreationKey=java.util.UUID.randomUUID().toString();_state.value=_state.value.copy(editing=kind,selected=null)};fun editOwner(x:JsonObject){if(_state.value.saving)return;_state.value=_state.value.copy(editing="owner-edit",selected=x)};fun adjustAccount(x:JsonObject){closeOwnerHistory();_state.value=_state.value.copy(editing="adjustments",selected=x)};fun editAccount(x:JsonObject){_state.value=_state.value.copy(editing="accounts",selected=x)};fun disableAccount(id:String)=viewModelScope.launch{try{api.disableMoneyAccount(id);load()}catch(e:Exception){fail(e)}};fun loanPayment(x:JsonObject){_state.value=_state.value.copy(editing="loan-payments",selected=x)};fun close(){if(_state.value.saving)return;_state.value=_state.value.copy(editing=null,selected=null)};fun save(kind:String,p:JsonObject)=viewModelScope.launch{if(_state.value.saving)return@launch;_state.value=_state.value.copy(saving=true,error=null);try{if(kind=="owner-edit")api.updateOwnerIdentity(_state.value.selected?.get("id")?.jsonPrimitive?.contentOrNull?:throw IllegalArgumentException("Owner is missing"),p)else if(kind=="accounts")api.saveMoneyAccount(_state.value.selected?.get("id")?.jsonPrimitive?.contentOrNull,if(_state.value.selected==null)com.salespunch360.mobile.account.moneyAccountCreationPayload(p,accountCreationKey)else p)else api.moneyAction(kind,p);_state.value=_state.value.copy(saving=false);close();load()}catch(e:Exception){fail(e)}};private fun fail(e:Exception){_state.value=_state.value.copy(loading=false,saving=false,error=if(e is IOException)"Offline. No cash/bank change was confirmed." else (e as? ApiException)?.serverMessage?:"Cash/bank action rejected by server.")}}
